CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE processing_status AS ENUM ('detected','processing','verifying','ready','awaiting_review','scheduled','publishing','published','rejected','duplicate','failed','corrected');
CREATE TYPE editorial_mode AS ENUM ('automatic','hybrid','manual');
CREATE TABLE sources(id text PRIMARY KEY,name text NOT NULL,enabled boolean NOT NULL DEFAULT false,source_type text NOT NULL,acquisition_method text NOT NULL,feed_url text,api_endpoint text,priority integer NOT NULL CHECK(priority BETWEEN 0 AND 100),trust_score integer NOT NULL CHECK(trust_score BETWEEN 0 AND 100),language text NOT NULL,country text,categories text[] NOT NULL DEFAULT '{}',poll_interval_ms integer NOT NULL DEFAULT 30000,requires_license boolean NOT NULL DEFAULT false,credentials_configured boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_credentials_metadata(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id text NOT NULL REFERENCES sources(id),credential_name text NOT NULL,configured boolean NOT NULL DEFAULT false,last_rotated_at timestamptz,UNIQUE(source_id,credential_name));
CREATE TABLE news_items(id text PRIMARY KEY,source_id text NOT NULL REFERENCES sources(id),external_id text NOT NULL,original_language text NOT NULL,original_title text NOT NULL,original_summary text,original_url text NOT NULL,canonical_url text NOT NULL,url_hash text NOT NULL,raw_payload jsonb,raw_payload_hash text NOT NULL,published_at timestamptz NOT NULL,discovered_at timestamptz NOT NULL DEFAULT now(),country text,region text,category text,entities jsonb NOT NULL DEFAULT '[]',claims jsonb NOT NULL DEFAULT '[]',breaking_score integer NOT NULL,importance_score integer NOT NULL,confidence_score integer NOT NULL,turkey_relevance_score integer NOT NULL DEFAULT 0,processing_status processing_status NOT NULL DEFAULT 'detected',correlation_id text NOT NULL,UNIQUE(source_id,external_id));
CREATE TABLE story_clusters(id text PRIMARY KEY,fingerprint text NOT NULL,headline text NOT NULL,entities jsonb NOT NULL DEFAULT '[]',first_seen_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL,published boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
CREATE TABLE story_cluster_items(cluster_id text REFERENCES story_clusters(id),news_item_id text REFERENCES news_items(id),similarity real NOT NULL,PRIMARY KEY(cluster_id,news_item_id));
CREATE TABLE claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cluster_id text NOT NULL REFERENCES story_clusters(id),text text NOT NULL,type text NOT NULL,confidence integer NOT NULL,supporting_count integer NOT NULL DEFAULT 0,contradicting_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claim_sources(claim_id uuid REFERENCES claims(id),source_id text REFERENCES sources(id),stance text NOT NULL CHECK(stance IN ('support','contradict')),news_item_id text REFERENCES news_items(id),PRIMARY KEY(claim_id,source_id,news_item_id));
CREATE TABLE publication_candidates(id text PRIMARY KEY,cluster_id text NOT NULL REFERENCES story_clusters(id),text text NOT NULL,weighted_character_count integer NOT NULL,source_ids text[] NOT NULL,importance_score integer NOT NULL,breaking_score integer NOT NULL,confidence_score integer NOT NULL,publish_mode text NOT NULL,generated_at timestamptz NOT NULL,status processing_status NOT NULL,ai_input jsonb,ai_output jsonb,validation_result jsonb,approved_by uuid,idempotency_key text UNIQUE NOT NULL);
CREATE TABLE published_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id text NOT NULL UNIQUE REFERENCES publication_candidates(id),publisher text NOT NULL DEFAULT 'x',external_post_id text UNIQUE,external_url text,text text NOT NULL,published_at timestamptz NOT NULL DEFAULT now(),source_published_at timestamptz,x_confirmed_at timestamptz,status text NOT NULL,audit jsonb NOT NULL DEFAULT '{}');
CREATE TABLE post_sources(post_id uuid REFERENCES published_posts(id),source_id text REFERENCES sources(id),news_item_id text REFERENCES news_items(id),PRIMARY KEY(post_id,source_id,news_item_id));
CREATE TABLE corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES published_posts(id),kind text NOT NULL,reason text NOT NULL,replacement_text text NOT NULL,status processing_status NOT NULL DEFAULT 'awaiting_review',created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE TABLE source_health(id bigserial PRIMARY KEY,source_id text NOT NULL REFERENCES sources(id),checked_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL,http_status integer,response_ms integer,items_found integer,parse_failures integer NOT NULL DEFAULT 0,consecutive_errors integer NOT NULL DEFAULT 0,error text);
CREATE TABLE processing_logs(id bigserial PRIMARY KEY,correlation_id text NOT NULL,event text NOT NULL,level text NOT NULL DEFAULT 'info',payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editorial_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,enabled boolean NOT NULL DEFAULT true,definition jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,display_name text NOT NULL,role text NOT NULL CHECK(role IN ('admin','editor','viewer')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX news_items_published_idx ON news_items(published_at DESC);CREATE INDEX news_items_discovered_idx ON news_items(discovered_at DESC);CREATE INDEX news_items_status_idx ON news_items(processing_status);CREATE INDEX news_items_url_hash_idx ON news_items(url_hash);CREATE INDEX cluster_fingerprint_idx ON story_clusters(fingerprint);CREATE INDEX cluster_items_item_idx ON story_cluster_items(news_item_id);CREATE INDEX logs_correlation_idx ON processing_logs(correlation_id,created_at);CREATE INDEX health_source_idx ON source_health(source_id,checked_at DESC);
